json IovPayloadDto::toJson() const {
  json js = json::object();

  js["since"] = since;
  js["insertionTime"] = insertionTime;
  js["version"] = version;
  js["objectType"] = objectType;
  js["objectName"] = objectName;
  if (compressionType.has_value())
    js["compressionType"] = compressionType.value();
  js["size"] = size;
  js["payloadHash"] = payloadHash;

  return js;
}

IovPayloadDto IovPayloadDto::fromJson(const json &j) {
  IovPayloadDto dto;

  dto.since = j.value<uint64_t>("since", 0);
  dto.insertionTime = j.value("insertionTime", "");
  dto.version = j.value("version", "");
  dto.objectType = j.value("objectType", "");
  dto.objectName = j.value("objectName", "");

  if (j.contains("compressionType") && !j["compressionType"].is_null())
    dto.compressionType = j.value("compressionType", "");

  dto.size = j.value<int>("size", 0);
  dto.payloadHash = j.value("payloadHash", "");

  return dto;
}
